from typing import List

def min_coins(coins: List[int], amount: int) -> int:
    # dp[i] = minimum coins needed to make amount i
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0

    for coin in coins:
        for x in range(coin, amount + 1):
            if dp[x - coin] + 1 < dp[x]:
                dp[x] = dp[x - coin] + 1

    return dp[amount] if dp[amount] <= amount else -1
